begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select plan(36);
insert into auth.users (id,email,raw_user_meta_data) values
 ('20000000-0000-0000-0000-000000000001','m2-sql-a@example.invalid','{"display_name":"Original Author"}'),
 ('20000000-0000-0000-0000-000000000002','m2-sql-b@example.invalid','{"display_name":"Other Learner"}');
insert into learning_sessions(id,user_id,title,mesechta,daf,context_type) values
 ('21000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','Chullin 57a','Chullin','57a','DAF_YOMI'),
 ('21000000-0000-0000-0000-000000000002','20000000-0000-0000-0000-000000000002','Private B',null,null,'OTHER');
create temporary table m2_state (note_id uuid,v1 uuid,v2 uuid,v3 uuid);
grant select,insert,update on m2_state to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',true);
select is((select count(*)::integer from learning_sessions),1,'Private sessions are isolated');
select throws_like($q$insert into public.learning_sessions(user_id,title) values ('20000000-0000-0000-0000-000000000002','Forged')$q$,'%row-level security%','Cannot create a session for another user');
insert into m2_state(note_id) select public.save_learning_note(null,null,'Siman or definition','My core idea','Original body with refs 1, 2, 3, 4, 5, 6','Summary','Initial save',array['21000000-0000-0000-0000-000000000001']::uuid[],'[{"facet_type":"CORPUS","facet_value":"Gemara"},{"facet_type":"DOMAIN","facet_value":"Halacha"}]','[{"reference_label":"Chullin 57a"},{"reference_label":"Rashi"},{"reference_label":"Tosafos"},{"reference_label":"Rambam"},{"reference_label":"Shulchan Aruch"}]');
update m2_state set v1 = (select current_version_id from notes where id = note_id);
select is((select count(*)::integer from note_versions),1,'Initial save creates exactly one version');
select is((select version_number from note_versions),1,'Initial version is numbered one');
select is((select author_display_name from note_versions),'Original Author','Version snapshots server-side author attribution');
select is((select author_thesis_snapshot from note_versions),'My core idea','Version preserves author thesis');
select is((select count(*)::integer from note_facets),2,'Gemara and Halacha coexist as independent facets');
select is((select count(*)::integer from note_sessions),1,'Note is linked to its daf session');
select is((select count(*)::integer from note_anchor_sources),5,'Five anchors are allowed');
select ok((select bool_and(verification_status = 'UNVERIFIED') from note_anchor_sources),'Anchors are explicitly unverified');
select throws_ok($q$select public.save_learning_note(null,null,'Too many','Idea','Body','','Create','{}','[]','[{"reference_label":"1"},{"reference_label":"2"},{"reference_label":"3"},{"reference_label":"4"},{"reference_label":"5"},{"reference_label":"6"}]')$q$,'22023','A note may have at most five anchor references','Six anchors are rejected server-side');
select is((select count(*)::integer from notes),1,'Rejected save creates no orphan note');
select ok((select body like '%1, 2, 3, 4, 5, 6%' from note_versions),'Body reference count is not capped at five');
update profiles set display_name = 'Renamed Author';
select public.save_learning_note(note_id,v1,'Edited title','Updated thesis','Second body','','Edit one','{}','[{"facet_type":"DOMAIN","facet_value":"Halacha"}]','[]') from m2_state;
update m2_state set v2 = (select current_version_id from notes where id = note_id);
select public.save_learning_note(note_id,v2,'Third title','Third thesis','Third body','','Edit two','{}','[{"facet_type":"DOMAIN","facet_value":"Halacha"}]','[]') from m2_state;
update m2_state set v3 = (select current_version_id from notes where id = note_id);
select is((select count(*)::integer from note_versions),3,'Two edits append two versions');
select is((select body from note_versions where id = (select v1 from m2_state)),'Original body with refs 1, 2, 3, 4, 5, 6','Original content remains unchanged');
select is((select parent_version_id from note_versions where id = (select v3 from m2_state)),(select v2 from m2_state),'Parent chain tracks the previous current version');
select is((select author_display_name from note_versions where id = (select v1 from m2_state)),'Original Author','Profile rename cannot rewrite old attribution');
select is((select author_display_name from note_versions where id = (select v3 from m2_state)),'Renamed Author','New save snapshots the current display name');
select throws_ok($q$select public.save_learning_note(note_id,v1,'Stale','Stale thesis','Stale','','Stale','{}','[]','[]') from m2_state$q$,'PT409','This note has changed. Reload it before saving your draft.','Stale editor cannot overwrite newer work');
select throws_like($q$select public.save_learning_note(note_id,v3,'Bad metadata','Idea','Bad','','Bad','{}','[{"facet_type":"NOT_A_FACET","facet_value":"Invalid"}]','[]') from m2_state$q$,'%violates check constraint%','Invalid metadata aborts the whole save');
select is((select count(*)::integer from note_versions),3,'Failed save appends no partial version');
select throws_ok($q$update public.note_versions set body = 'Overwrite'$q$,'42501','permission denied for table note_versions','Client cannot overwrite history');
select throws_ok('delete from public.note_versions','42501','permission denied for table note_versions','Client cannot delete history');
select throws_ok($q$select public.save_learning_note(note_id,v3,'Cross link','Idea','Body','','Attempt',array['21000000-0000-0000-0000-000000000002']::uuid[],'[]','[]') from m2_state$q$,'42501','A linked learning session is unavailable','Cannot link another learners session');
select public.restore_learning_note(note_id,v1,v3) from m2_state;
select is((select count(*)::integer from note_versions),4,'Restore appends a fourth version');
select is((select body from note_versions where id = (select current_version_id from notes)),'Original body with refs 1, 2, 3, 4, 5, 6','Restore copies original body');
select is((select author_thesis from notes),'My core idea','Restore restores the approved thesis');
select is((select title from notes),'Siman or definition','Restore restores the title');
select is((select body from note_versions where id = (select v3 from m2_state)),'Third body','Restore retains the version it replaces');
select is((select count(*)::integer from note_facets),1,'Restore preserves current organization');
reset role;
update profiles set role = 'GLOBAL_ADMIN' where id = '20000000-0000-0000-0000-000000000002';
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000002',true);
select is((select count(*)::integer from notes),0,'Global admin cannot read another learners notes');
select is((select count(*)::integer from note_versions),0,'Global admin cannot read another learners history');
select is((select count(*)::integer from note_facets),0,'Facet metadata stays private');
select throws_ok($q$select public.restore_learning_note(note_id,v1,v3) from m2_state$q$,'42501','Note unavailable','Restore function enforces ownership');
select throws_ok($q$select public.save_learning_note(note_id,v3,'Hijack','Idea','Body','','Hijack','{}','[]','[]') from m2_state$q$,'42501','Note unavailable','Save function enforces ownership');
reset role;
set local role anon;
select throws_ok('select * from public.notes','42501','permission denied for table notes','Anonymous notes access is denied');
reset role;
select * from finish();
rollback;
